# Remove intentional skips and anything we may already have
EXISTING = {
  "adobe-podcast","chatgpt","claude","claude-code","cursor","dall-e-3","deepseek-v4-1-flash",
  "devin","devin-desktop","elevenlabs","figma-ai","intercom-fin","gemini","github-copilot",
  "grok-4-7","ideogram","jasper","langchain","midjourney","mistral","n8n","notebooklm","ollama",
  "perplexity","pika","replit-agent","runway","stable-diffusion",
}

TOOLS = [t for t in TOOLS if not t.get("skip") and t["slug"] not in EXISTING]


def sql_str(value: str) -> str:
  return "'" + value.replace("'", "''") + "'"


def sql_array(values: list[str]) -> str:
  if not values:
    return "ARRAY[]::text[]"
  return "ARRAY[" + ", ".join(sql_str(v) for v in values) + "]::text[]"


def bool_sql(v: bool | None) -> str:
  if v is None:
    return "null"
  return "true" if v else "false"


def main() -> None:
  pubs = sorted({t["publisher"] for t in TOOLS})
  lines: list[str] = []
  lines.append("-- Seed well-known AI tools (idempotent by slug)")
  lines.append("do $$")
  lines.append("declare")
  lines.append("  v_publisher_id uuid;")
  lines.append("  v_tool_id uuid;")
  lines.append("  v_type_id uuid;")
  lines.append("  v_source_id uuid;")
  lines.append("  v_cat_id uuid;")
  lines.append("  v_plat_id uuid;")
  lines.append("  v_primary boolean;")
  lines.append("begin")

  for pub in pubs:
    lines.append(f"  insert into publishers (name) values ({sql_str(pub)}) on conflict (name) do nothing;")

  for t in TOOLS:
    lines.append("")
    lines.append(f"  -- {t['name']}")
    lines.append(f"  select id into v_publisher_id from publishers where name = {sql_str(t['publisher'])};")
    lines.append(
      "  insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at)"
    )
    lines.append("  values (")
    lines.append(f"    {sql_str(t['name'])}, {sql_str(t['slug'])}, v_publisher_id,")
    lines.append(f"    {sql_str(t['summary'])}, {sql_str(t['description'])}, {sql_str(t['url'])},")
    lines.append(f"    'published', {sql_str(t['pricing'])}, {sql_str(t['price'])},")
    lines.append(f"    {bool_sql(t['api'])}, {bool_sql(t['oss'])}, {bool_sql(t['local'])},")
    lines.append(f"    {sql_array(t['kw'])}, {sql_array(t['str'])}, {sql_array(t['lim'])}, {sql_array(t['aud'])},")
    lines.append("    current_date")
    lines.append("  ) on conflict (slug) do nothing;")
    lines.append(f"  select id into v_tool_id from tools where slug = {sql_str(t['slug'])};")
    lines.append("  if v_tool_id is not null then")
    lines.append(f"    select id into v_type_id from solution_types where name = {sql_str(t['type'])};")
    lines.append("    if v_type_id is not null then")
    lines.append("      insert into tool_types (tool_id, solution_type_id, is_primary)")
    lines.append("      values (v_tool_id, v_type_id, true)")
    lines.append("      on conflict do nothing;")
    lines.append("    end if;")
    lines.append(f"    insert into sources (url, publisher, source_type, reliability_level)")
    lines.append(f"    values ({sql_str(t['url'])}, {sql_str(t['publisher'])}, 'official', 'A')")
    lines.append("    on conflict (url) do nothing;")
    lines.append(f"    select id into v_source_id from sources where url = {sql_str(t['url'])};")
    lines.append("    if v_source_id is not null then")
    lines.append("      insert into tool_sources (tool_id, source_id, claim_key, verified_at)")
    lines.append("      values (v_tool_id, v_source_id, 'general', current_date)")
    lines.append("      on conflict do nothing;")
    lines.append("    end if;")

    for i, cat in enumerate(t["cats"]):
      primary = "true" if i == 0 else "false"
      lines.append(f"    select id into v_cat_id from categories where name = {sql_str(cat)};")
      lines.append("    if v_cat_id is not null then")
      lines.append("      insert into tool_categories (tool_id, category_id, is_primary)")
      lines.append(f"      values (v_tool_id, v_cat_id, {primary})")
      lines.append("      on conflict do nothing;")
      lines.append("    end if;")

    for plat in t["plats"]:
      lines.append(f"    select id into v_plat_id from platforms where label = {sql_str(plat)};")
      lines.append("    if v_plat_id is not null then")
      lines.append("      insert into tool_platforms (tool_id, platform_id, status)")
      lines.append("      values (v_tool_id, v_plat_id, 'available')")
      lines.append("      on conflict do nothing;")
      lines.append("    end if;")

    lines.append("  end if;")

  lines.append("end $$;")
  sql = "\n".join(lines) + "\n"
  out = Path("scripts/seed_known_tools.sql")
  out.write_text(sql, encoding="utf-8")
  meta = {"count": len(TOOLS), "slugs": [t["slug"] for t in TOOLS]}
  Path("scripts/seed_known_tools.meta.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
  print(f"Wrote {out} with {len(TOOLS)} tools ({out.stat().st_size} bytes)")


if __name__ == "__main__":
  main()
